type WorkloadsByRegionRow struct {
	Provider    string  `json:"provider"`
	ServiceName string  `json:"service_name"`
	RegionID    string  `json:"region_id"`
	EnergyKwh   float64 `json:"energy_kwh"`
	CarbonKg    float64 `json:"carbon_kg"`
}

// Input of the region_shift generator: last-window carbon per workload (read-only view of the carbon schema).
func (q *Queries) WorkloadsByRegion(ctx context.Context, arg WorkloadsByRegionParams) ([]WorkloadsByRegionRow, error) {
	rows, err := q.db.Query(ctx, workloadsByRegion,
		arg.TenantID,
		arg.ProjectID,
		arg.MethodologyVersion,
		arg.FromTs,
		arg.ToTs,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WorkloadsByRegionRow{}
	for rows.Next() {
		var i WorkloadsByRegionRow
		if err := rows.Scan(
			&i.Provider,
			&i.ServiceName,
			&i.RegionID,
			&i.EnergyKwh,
			&i.CarbonKg,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
